@st.cache_data(ttl="12h", show_spinner=False)
def _load_trend_contracts(api_key: str, as_of: str):
    return get_front_contracts([c["product_code"] for c in COMMODITIES], api_key,
                               date.fromisoformat(as_of), n_contracts=TREND_CONTRACTS)


@st.cache_data(ttl="5m", show_spinner=False)
def _load_trend_prices(api_key: str, tickers: tuple[str, ...]) -> dict[str, float]:
    return get_prices(list(tickers), api_key)


def load_trend_curves(api_key: str, as_of: str):
    """(curves, errors): every market's front contracts, each with a live price. Which
    contracts are the front ones only changes when one expires or lists, so a day's list is
    kept (12 h) and just the prices are re-read, every five minutes. A partial failure is shown
    but not kept: the caches are dropped, so the next rerun asks again."""
    contracts, listing_errors = _load_trend_contracts(api_key, as_of)
    errors = dict(listing_errors)
    tickers = tuple(sorted(c["ticker"] for rows in contracts.values() for c in rows))
    prices: dict[str, float] = {}
    if tickers:
        try:
            prices = _load_trend_prices(api_key, tickers)
        except MassiveApiError as e:
            errors.update({code: str(e) for code in contracts})
    curves: dict[str, pd.DataFrame] = {}
    for code, rows in contracts.items():
        priced = [{"ticker": c["ticker"], "expiration": pd.to_datetime(c["expiration"]).date(),
                   "price": prices[c["ticker"]]} for c in rows if c["ticker"] in prices]
        if priced:
            curves[code] = pd.DataFrame(priced)
        else:
            errors.setdefault(code, f"Massive returned no priced {code} contracts.")
    if errors:
        _load_trend_contracts.clear()
        _load_trend_prices.clear()
    return curves, errors


@st.cache_resource(ttl="6h", show_spinner=False)
def _settlement_bank(as_of: str) -> dict[tuple[str, str, int], pd.Series]:
    return settlement_bank.load_bank([c["product_code"] for c in COMMODITIES], BANK_FIRST_YEAR)


def load_settlement_bank(as_of: str) -> dict[tuple[str, str, int], pd.Series]:
    """Settlements banked in Snowflake since late 2021, or {} when Snowflake is off or
    unreachable. The tab then asks Massive instead: slower (about a minute), and a year
    shorter for meal, oil and wheat, since Massive's per-contract history starts later."""
    try:
        return _settlement_bank(as_of)
    except Exception:  # Snowflake fails in many ways; none of them should blank the tab
        return {}


@st.cache_data(ttl="6h", show_spinner=False)
def load_trend_histories(tickers: tuple[str, ...], api_key: str, as_of: str) -> dict[str, pd.Series]:
    """Daily settlements of the front contracts, today's session included."""
    return get_settlement_histories(list(tickers), api_key, max_workers=len(tickers),
                                    retry_empty=True)


@st.cache_data(ttl="12h", show_spinner=False)
def load_trend_analogs(tickers: tuple[str, ...], api_key: str, as_of: str) -> dict[str, pd.Series]:
    """Prior-year contracts for the seasonal read. Massive serves about one history a second
    however many are asked for at once, so a cold load of ~60 takes about a minute."""
    return get_settlement_histories(list(tickers), api_key, max_workers=16, retry_empty=True)


def contract_letter(ticker: str, code: str) -> str:
    """The month letter of an outright like ZCZ6, or "" for anything else."""
    suffix = ticker[len(code):]
    return suffix[0] if len(suffix) == 2 and suffix[0] in MONTH_LETTERS else ""


def banked_series(bank: dict, code: str, letter: str, year: int) -> "pd.Series | None":
    series = bank.get((code, letter, year))
    return series if series is not None and len(series) else None


def settled_before(series: "pd.Series | None", as_of: date) -> "pd.Series | None":
    """The sessions before `as_of`. Massive's bar for the session in progress carries its last
    trade, not a settlement, and the bank only holds a day once its job has run, so cutting both
    at the same place makes the averages mean the same thing whichever source supplied them."""
    if series is None or not len(series):
        return series
    return series[[day < as_of for day in series.index]]


def load_trend_fronts(api_key: str, as_of: date, bank: dict) -> list[dict]:
    """The two nearest contracts of every market, with live price and settlement history. A
    market that couldn't be loaded appears once, carrying its error. History comes from the
    settlement bank while it is current for that contract (a weekend or holiday is fine; a
    missed job isn't), and from Massive otherwise."""
    iso = as_of.isoformat()
    curves, errors = load_trend_curves(api_key, iso)
    fronts = {c["product_code"]: curves[c["product_code"]].head(2)
              for c in COMMODITIES if c["product_code"] in curves}
    histories: dict[str, pd.Series] = {}
    unbanked: list[str] = []
    for code, curve in fronts.items():
        for r in curve.itertuples():
            series = banked_series(bank, code, contract_letter(r.ticker, code), r.expiration.year)
            if series is not None and (as_of - series.index[-1]).days <= BANK_FRESH_DAYS:
                histories[r.ticker] = series
            else:
                unbanked.append(r.ticker)
    if unbanked:
        histories.update(load_trend_histories(tuple(unbanked), api_key, iso))
    out = []
    for commodity in COMMODITIES:
        code = commodity["product_code"]
        curve = fronts.get(code)
        if curve is None:
            out.append({"commodity": commodity, "error": errors.get(code, "no live contracts")})
            continue
        for r in curve.itertuples():
            out.append({"commodity": commodity, "ticker": r.ticker, "expiration": r.expiration,
                        "price": float(r.price), "letter": contract_letter(r.ticker, code),
                        "history": settled_before(histories.get(r.ticker), as_of)})
    return out


def trend_analog_plan(front: dict, as_of: date, legacy: pd.DataFrame,
                      bank: dict) -> dict[int, "pd.Series | str"]:
    """{years_back: history, or the Massive ticker to fetch it with} for the same contract
    month in prior years. The bundled pre-2022 file serves corn and soybeans, the settlement
    bank everything since late 2021 (the longer of the two wins where they overlap). Massive
    is asked only when there is no bank at all, and it has nothing before its first bar, so a
    year whose window opens earlier than that is skipped rather than fetched."""
    code = front["commodity"]["product_code"]
    letter = front["letter"]
    plan: dict[int, pd.Series | str] = {}
    if not letter:
        return plan
    for years_back, year in trend_board.analog_years(front["expiration"]):
        old = get_legacy_series(legacy, code, letter, year) if year <= 2021 else pd.Series(dtype=float)
        banked = banked_series(bank, code, letter, year)
        if len(old) and (banked is None or len(old) >= len(banked)):
            plan[years_back] = old
        elif banked is not None:
            plan[years_back] = banked
        elif (not bank and year >= MASSIVE_FLOOR.year
              and trend_board.shift_back(as_of, years=years_back) >= MASSIVE_FLOOR):
            plan[years_back] = f"{code}{letter}{year % 10}"
    return plan


def trend_rows(fronts: list[dict], as_of: date, plans: list[dict] | None = None,
               fetched: dict[str, pd.Series] | None = None):
    """[(commodity, ContractTrend | None, error | None)]. Without `plans` the seasonal read
    is left out, which is how the table first appears while its history is still loading."""
    rows = []
    for i, front in enumerate(fronts):
        if "error" in front:
            rows.append((front["commodity"], None, front["error"]))
            continue
        analogs = {}
        if plans is not None:
            for years_back, source in plans[i].items():
                series = source if isinstance(source, pd.Series) else (fetched or {}).get(source)
                if series is not None and len(series):
                    analogs[years_back] = series
        rows.append((front["commodity"], trend_board.contract_trend(
            front["ticker"], front["expiration"], front["price"], front["history"], analogs, as_of), None))
    return rows


def fmt_trend_change(change) -> str:
    if change is None:
        return "—"
    return f"{change[0]:+,.2f} ({change[1]:+.1%})"


def fmt_trend_seasonal(trend) -> str:
    read = trend.seasonal
    if read is None or read.label is None:
        return "—"
    tail = f" ({trend.horizon_days}d)" if trend.horizon_days < trend_board.HORIZON_DAYS else ""
    return f"{SEASONAL_ARROW[read.label]} {read.label} {read.average:+.1%}{tail}"


def fmt_trend_years(trend) -> str:
    read = trend.seasonal
    if read is None:
        return "—"
    if read.label is None:
        return f"only {read.years} yr{'s' if read.years != 1 else ''}"
    return f"{read.higher} / {read.neutral} / {read.weaker} of {read.years}"


def trend_frames(rows, ready: bool) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """(display, cell styles, export): the table as shown, a CSS string per cell, and the
    same rows as plain numbers for CSV. `ready` is False while the seasonal is still loading."""
    shown, styles, export = [], [], []
    for market_no, commodity in enumerate(COMMODITIES):
        mine = [(t, e) for c, t, e in rows if c is commodity]
        for i, (trend, _) in enumerate(mine):
            first = i == 0
            base = (GROUP_BAND if market_no % 2 == 0 else "") + (TREND_GROUP_TOP if first else "")
            style = dict.fromkeys(TREND_COLUMNS, base)
            # The market's name on its first row, its price unit under it.
            label = commodity["label"] if first else commodity["unit"]
            style["Market"] = base + ("font-weight:600;" if first else "color:#6b7280;")
            if trend is None:
                shown.append({**dict.fromkeys(TREND_COLUMNS, "—"), "Market": label,
                              "Contract": "unavailable"})
                styles.append(style)
                export.append({"market": commodity["label"], "contract": "unavailable"})
                continue
            code = commodity["product_code"]
            row = {"Market": label,
                   "Contract": f"{code}{trend.ticker[len(code)]}{trend.expiration.year % 100:02d}",
                   "Last": f"{trend.last:,.2f}"}
            for col, period in (("vs 1 wk", "1 week"), ("vs 1 mo", "1 month"), ("vs 1 yr", "1 year")):
                change = trend.changes[period]
                row[col] = fmt_trend_change(change)
                if change is not None and change[0] != 0:
                    style[col] = base + (TREND_UP if change[0] > 0 else TREND_DOWN)
            if ready:
                row["Seasonal, next 30d"] = fmt_trend_seasonal(trend)
                row["Years ▲ / ● / ▼"] = fmt_trend_years(trend)
                if trend.seasonal is not None and trend.seasonal.label:
                    style["Seasonal, next 30d"] = base + SEASONAL_STYLE[trend.seasonal.label]
            else:
                row["Seasonal, next 30d"] = row["Years ▲ / ● / ▼"] = "loading…"
            for window in trend_board.SMA_WINDOWS:
                avg = trend.averages[window]
                row[f"SMA {window}"] = "—" if avg is None else f"{avg:,.2f}"
                if avg is not None and avg != trend.last:
                    style[f"SMA {window}"] = base + (TREND_UP if trend.last > avg else TREND_DOWN)
            shown.append(row)
            styles.append(style)

            read = trend.seasonal
            record = {"market": commodity["label"], "unit": commodity["unit"], "contract": row["Contract"],
                      "ticker": trend.ticker, "expires": trend.expiration, "last": trend.last}
            for tag, period in (("1w", "1 week"), ("1m", "1 month"), ("1y", "1 year")):
                change = trend.changes[period]
                record[f"chg_{tag}"] = None if change is None else round(change[0], 4)
                record[f"chg_{tag}_pct"] = None if change is None else round(change[1] * 100, 2)
            for window in trend_board.SMA_WINDOWS:
                avg = trend.averages[window]
                record[f"sma_{window}"] = None if avg is None else round(avg, 4)
            record.update({
                "seasonal": read.label if read else None,
                "seasonal_avg_pct": None if read is None else round(read.average * 100, 2),
                "seasonal_years": None if read is None else read.years,
                "years_higher": None if read is None else read.higher,
                "years_neutral": None if read is None else read.neutral,
                "years_weaker": None if read is None else read.weaker,
                "seasonal_days": trend.horizon_days,
            })
            export.append(record)

    return (pd.DataFrame(shown, columns=TREND_COLUMNS), pd.DataFrame(styles, columns=TREND_COLUMNS),
            pd.DataFrame(export))


def draw_trend_table(rows, ready: bool) -> tuple[pd.DataFrame, "pd.io.formats.style.Styler"]:
    """Draw the snapshot table; returns the plain-number frame for CSV and the styled table
    for the PNG."""
    display, styles, export = trend_frames(rows, ready)
    styler = display.style.apply(lambda _: styles, axis=None)

    def right_text(**options):
        return st.column_config.TextColumn(alignment="right", **options)

    # Every figure is pre-formatted text (a missing one reads "—", where a numeric column would
    # say "None"), so the number columns are right-aligned by hand.
    column_config = {
        "Market": st.column_config.TextColumn(width=135),
        "Contract": st.column_config.TextColumn(width=80),
        "Last": right_text(width=72, help="Live price, in the market's quote units (shown under its name)."),
        "vs 1 wk": right_text(help="Change against this contract's settlement a week ago."),
        "vs 1 mo": right_text(help="Change against this contract's settlement a month ago."),
        "vs 1 yr": right_text(help="Change against this contract's settlement a year ago."),
        "Seasonal, next 30d": st.column_config.TextColumn(
            help="Average move of the same contract month over the same 30 days in prior years. "
                 "Higher: +3% or more. Weaker: -3% or less. Neutral: in between."),
        "Years ▲ / ● / ▼": st.column_config.TextColumn(
            width=118,
            help="How many prior years finished up more than 3%, inside +/-3%, and down more "
                 "than 3%, out of the years on file."),
        **{f"SMA {w}": right_text(width=76, help=f"Simple average of the last {w} daily "
                                  "settlements. Green: price above it. Red: below.")
           for w in trend_board.SMA_WINDOWS},
    }
    st.dataframe(styler, hide_index=True, width="stretch", column_config=column_config,
                 height=min(35 * (len(display) + 1) + 3, 900))
    return export, styler


TREND_PNG_NOTE = (
    f"{DELAYED_QUOTES_NOTE} Changes are against the same contract's settlement a week, a month "
    "and a year earlier. Averages are the last 20, 100 and 200 daily settlements before today. "
    "Seasonal is the average move of the same contract month over the same 30 days in prior "
    "years (up to 15): Higher at +3% or more, Weaker at -3% or less, Neutral between."
)


def history_source_note(bank: dict) -> str:
    """Where the settlement history came from, so a stale or missing bank is visible."""
    if bank:
        latest = max(series.index[-1] for series in bank.values() if len(series))
        return f"History: JSA's Snowflake settlement bank, through {latest:%b %d}."
    if settlement_bank.use_snowflake():
        return ("History: Massive daily settlements. The Snowflake settlement bank couldn't be "
                "read just now, so this load took longer; it tries again in a few minutes.")
    return ("History: Massive daily settlements. This copy isn't connected to the Snowflake "
            "settlement bank, so the first load takes about a minute.")


def render_trend_legend():
    chips = "".join(
        f'<span style="{SEASONAL_STYLE[label]}padding:2px 10px;border-radius:4px;font-size:0.82rem;'
        f'white-space:nowrap;">{SEASONAL_ARROW[label]} {label} &middot; {txt}</span>'
        for label, txt in (("Higher", "avg move &ge; +3%"),
                           ("Neutral", "within &plusmn;3%"),
                           ("Weaker", "avg move &le; &minus;3%")))
    st.markdown(
        '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:2px 0 6px;">'
        '<span style="font-size:0.82rem;color:#6b7280;">Seasonal read</span>' + chips + "</div>",
        unsafe_allow_html=True,
    )


def render_trends(api_key: str, as_of: date):
    head = st.container(horizontal=True, vertical_alignment="center")
    with head:
        st.markdown("##### Trends")
        st.markdown(
            f"<div style='text-align:right;font-size:0.82rem;padding-top:10px;'>"
            f"<b>Date</b>&nbsp;&nbsp;{as_of:%m/%d/%Y}</div>",
            unsafe_allow_html=True,
        )
    st.caption(
        "The two front months of each market: where they trade against a week, a month and a "
        "year ago, their 20, 100 and 200-day averages, and what the seasonal says about the "
        "next 30 days."
    )
    st.caption(DELAYED_QUOTES_NOTE)
    render_trend_legend()

    iso = as_of.isoformat()
    with st.spinner("Loading the front months…"):
        bank = load_settlement_bank(iso)
        fronts = load_trend_fronts(api_key, as_of, bank)

    legacy = load_legacy_history_cached()
    plans = [trend_analog_plan(f, as_of, legacy, bank) if "error" not in f else {} for f in fronts]
    wanted = tuple(sorted({src for plan in plans for src in plan.values() if isinstance(src, str)}))
    fetched: dict[str, pd.Series] = {}
    slot = st.empty()
    if wanted:
        # No settlement bank here, so the seasonal needs ~60 histories from Massive, about a
        # minute. Prices, changes and averages are ready now: draw the table without the seasonal
        # first and redraw it in place once the history arrives.
        with slot.container():
            draw_trend_table(trend_rows(fronts, as_of), ready=False)
        with st.spinner("Loading the seasonal history (about a minute the first time)…"):
            fetched = load_trend_analogs(wanted, api_key, iso)
    rows = trend_rows(fronts, as_of, plans, fetched)
    with slot.container():
        export, styler = draw_trend_table(rows, ready=True)
    export_row(export, "trends_snapshot", key="trends",
               table={"styler": styler, "title": f"Trends snapshot · {as_of:%b %d, %Y}",
                      "note": TREND_PNG_NOTE})

    st.caption(
        "Changes compare the live price with that same contract's settlement a week, a month and a "
        "year earlier. Averages are the simple mean of the contract's last 20, 100 and 200 daily "
        "settlements before today; green means the price is above it, red below. Seasonal takes "
        "the same contract month in each prior year (up to 15) and measures its move over the same "
        "30 days from today's date. The average sets the read, and the years column counts how "
        "many of those years finished up more than 3%, inside ±3%, or down more than 3%. A "
        "contract that expires inside 30 days is read to its expiry (marked with the days used); "
        "a dash means it expires within 10 days or has too little history on file."
    )
    st.caption(history_source_note(bank))
    years_on_file: dict[str, int] = {}
    for commodity, trend, _ in rows:
        if trend is not None and trend.seasonal is not None:
            label = commodity["label"]
            years_on_file[label] = max(years_on_file.get(label, 0), trend.seasonal.years)
    thin = [f"{label} ({n})" for label, n in years_on_file.items() if n < trend_board.SEASONAL_YEARS]
    if thin:
        st.caption(
            f"Fewer than {trend_board.SEASONAL_YEARS} years of settlements are on file for "
            + ", ".join(thin) + ", so their seasonal rests on the years shown."
        )
    for commodity, trend, error in rows:
        if trend is None:
            st.warning(f"{commodity['label']}: {error}")


def refresh_prices():
    # Quotes only: settlement history is cached for hours on purpose and re-pulling it takes minutes.
    for loader in (load_curve, _load_trend_prices):
        loader.clear()


def render() -> None:
    """The Grain Futures Seasonals page: Trends, one tab per commodity, the cross-commodity spread and the report calendar."""
    st.markdown("### Grain Futures Seasonals")
    asof_col, refresh_col = st.columns([6, 1], vertical_alignment="center")
    with asof_col:
        st.caption(
            "Live CBOT grain futures, aligned across prior contract years to reveal seasonal "
            "patterns in outright price and in calendar spreads. "
            f"Data as of {datetime.now():%b %d, %Y %I:%M %p} · quotes delayed per Massive API."
        )
    with refresh_col:
        if st.button("Refresh prices", icon=":material/refresh:", width="stretch", key="seasonals_refresh",
                     help="Re-read live quotes now instead of waiting out the 5-minute cache. "
                          "Settlement-history charts are not re-pulled."):
            refresh_prices()
            st.toast("Fetching fresh prices…")
    st.caption(DATA_START_NOTE)
    st.caption(FND_NOTE)

    api_key = get_api_key()
    if not api_key:
        st.error("The futures data feed is not set up on this deployment (MASSIVE_API_KEY is missing).")
        return

    as_of = date.today()
    nass_years = tuple(range(2021, as_of.year + 1))

    st.caption("Report markers — vertical lines on the price/candlestick charts:")
    marker_row = st.container(horizontal=True, vertical_alignment="center")
    with marker_row:
        show_wasde = st.checkbox("WASDE", value=True, key="show_wasde")
        show_nass_major = st.checkbox(
            "NASS (major reports)", value=True, key="show_nass_major",
            help="Crop Production, Grain Stocks, Acreage, Prospective Plantings, "
                 "Winter Wheat & Canola Seedings, Small Grains Summary.",
        )
        show_crop_progress = st.checkbox(
            "NASS Crop Progress (weekly)", value=False, key="show_crop_progress",
            help="Off by default — weekly releases add a lot of lines.",
        )

    # The WASDE and NASS calendars take ~30 s to fetch cold, so they load when a tab that needs them opens.
    def report_dates_visible() -> dict[str, list[date]]:
        return _selected_report_dates(load_wasde_dates(), load_nass_dates(nass_years),
                                      show_wasde, show_nass_major, show_crop_progress)

    tab_labels = ["Trends"] + [c["label"] for c in COMMODITIES] + ["Cross-commodity spread", "Report calendar"]
    tabs = st.tabs(tab_labels, on_change="rerun", key="seasonals_tabs")
    with tabs[0]:
        if tabs[0].open:
            render_trends(api_key, as_of)
    for tab, commodity in zip(tabs[1:], COMMODITIES):
        with tab:
            if tab.open:
                st.caption(commodity["sublabel"])
                render_commodity(commodity, api_key, as_of, report_dates_visible())
    with tabs[-2]:
        if tabs[-2].open:
            render_cross_commodity_spread(api_key, as_of, report_dates_visible())
    with tabs[-1]:
        if tabs[-1].open:
            render_report_calendar(load_wasde_dates(), load_nass_dates(nass_years), as_of)
